package com.gk.jobhelper.service;
import com.gk.jobhelper.common.*;import com.gk.jobhelper.dto.*;import com.gk.jobhelper.entity.*;import com.gk.jobhelper.mapper.*;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.support.TransactionTemplate;
@Service public class RecruitmentPositionService {private final RecruitmentNoticeService notices;private final RecruitmentAttachmentMapper attachments;private final RecruitmentPositionMapper positions;private final RecruitmentAttachmentDownloadService downloader;private final List<RecruitmentPositionExtractor> extractors;private final TransactionTemplate transactions;public RecruitmentPositionService(RecruitmentNoticeService n,RecruitmentAttachmentMapper a,RecruitmentPositionMapper p,RecruitmentAttachmentDownloadService d,List<RecruitmentPositionExtractor> e,TransactionTemplate t){notices=n;attachments=a;positions=p;downloader=d;extractors=e;transactions=t;}public RecruitmentPositionExtractionResponse extract(Long noticeId){notices.detail(noticeId);List<RecruitmentAttachment> files=attachments.selectPositionDataByNoticeId(noticeId);if(files.isEmpty())throw new BusinessException(ApiResponse.CODE_BAD_REQUEST,"该公告没有可解析的岗位数据附件");int count=0,failed=0;for(RecruitmentAttachment file:files){try{DownloadedAttachment data=downloader.download(file);RecruitmentPositionExtractor extractor=extractors.stream().filter(e->e.supports(data.getFileType())).findFirst().orElseThrow(()->new BusinessException(ApiResponse.CODE_BAD_REQUEST,"岗位数据附件真实文件类型不是 Excel："+data.getFileType()));RecruitmentPositionExtractionResult result=extractor.extract(data,noticeId);if(result.positions.isEmpty())throw new BusinessException(ApiResponse.CODE_BAD_REQUEST,result.headerRows.isEmpty()?"岗位表未找到可识别表头":"岗位表没有有效岗位数据");transactions.execute(status->{positions.deleteByAttachmentId(file.getId());positions.insertBatch(result.positions);saveRequirements(result.positions);attachments.updateParseResult(file.getId(),data.getFileType(),"PARSED",null,result.positions.size(),LocalDateTime.now());return null;});count+=result.positions.size();}catch(Exception e){failed++;attachments.updateParseResult(file.getId(),file.getFileType(),"FAILED",safe(e.getMessage()),0,LocalDateTime.now());}}if(count==0&&failed>0)throw new BusinessException(ApiResponse.CODE_BAD_REQUEST,"岗位解析失败，请查看附件解析状态");return new RecruitmentPositionExtractionResponse(noticeId,files.size(),count,failed);}public List<RecruitmentPositionVO> list(Long noticeId){notices.detail(noticeId);return positions.selectByNoticeId(noticeId);}public RecruitmentPositionVO detail(Long id){RecruitmentPositionVO p=positions.selectById(id);if(p==null)throw new BusinessException(ApiResponse.CODE_BAD_REQUEST,"招聘岗位不存在: "+id);p.setRequirements(positions.selectRequirementsByPositionId(id));return p;}private void saveRequirements(List<RecruitmentPosition> list){List<RecruitmentRequirement> all=new ArrayList<>();for(RecruitmentPosition p:list){add(all,p,"EDUCATION",p.getEducationRequirement());add(all,p,"MAJOR",p.getMajorRequirement());add(all,p,"AGE",p.getAgeRequirement());add(all,p,"WORK_EXPERIENCE",p.getWorkYearsRequirement());add(all,p,"OTHER",p.getOtherRequirement());}if(!all.isEmpty())positions.insertRequirements(all);}private void add(List<RecruitmentRequirement> all,RecruitmentPosition p,String type,String raw){if(raw==null||raw.trim().isEmpty())return;RecruitmentRequirement r=new RecruitmentRequirement();r.setPositionId(p.getId());r.setRequirementType(type);r.setRequirementLevel(raw.contains("优先")?"PREFERRED":"REQUIRED");r.setRawText(raw);r.setSourceText(raw);r.setCreatedAt(LocalDateTime.now());all.add(r);}private String safe(String message){if(message==null)return "岗位附件解析失败";return message.length()>450?message.substring(0,450):message;}}
